effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  float sh = 1.0 - smoothstep(0.0, 0.58, l);
  float hi = smoothstep(0.40, 1.0, l);
  vec3 grade = c;
  grade = mix(grade, grade * vec3(0.55, 1.05, 1.18) * 1.18, sh * split);
  grade = mix(grade, grade * vec3(1.30, 0.92, 0.62) * 1.16, hi * split);
  grade = clamp((grade - 0.5) * contrast + 0.5, 0.0, 1.0);
  grade = mix(vec3(l), grade, saturation);
  vec2 p = (uv - 0.5) * vec2(acScreenSize.x / acScreenSize.y, 1.0);
  float edge = 1.0 - smoothstep(0.42, 0.82, length(p));
  grade *= mix(1.0, edge, vignette);
  vec3 col = mix(c, grade, mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * src.a, src.a);
}
